const token = settings.oauth_access_token;
if (!token) throw new Error('[auth] Connect Google Calendar before rendering');
const clamp = (value, min, max, fallback) => Math.min(max, Math.max(min, Number(value) || fallback));
const layout = settings.layout || 'upcoming';
const daysAhead = layout === 'agenda' ? 1 : layout === 'week' ? 7 : layout === 'month' ? 42 : clamp(settings.days_ahead, 1, 31, 14);
const maxEvents = clamp(settings.max_events, 1, 100, 24);
const calendarIds = String(settings.calendar_ids || 'primary').split(',').map(v => v.trim()).filter(Boolean).slice(0, 10);
const ignored = String(settings.ignored_phrases || '').split(',').map(v => v.trim().toLowerCase()).filter(Boolean);
const now = new Date();
const start = new Date(now);
if (layout === 'month') start.setDate(1);
if (settings.include_past !== 'yes') start.setTime(Math.max(start.getTime(), now.getTime()));
else start.setHours(0, 0, 0, 0);
let end = new Date(start);
if (layout === 'month') end = new Date(start.getFullYear(), start.getMonth() + 1, 7);
else end.setDate(end.getDate() + daysAhead);
const params = new URLSearchParams({
  timeMin: start.toISOString(), timeMax: end.toISOString(), singleEvents: 'true', orderBy: 'startTime',
  maxResults: String(Math.min(250, maxEvents * 3)), showDeleted: 'false',
});
if (settings.timezone) params.set('timeZone', String(settings.timezone));
const headers = { Authorization: 'Bearer ' + token, Accept: 'application/json' };
const batches = await Promise.all(calendarIds.map(async calendarId => {
  const url = 'https://www.googleapis.com/calendar/v3/calendars/' + encodeURIComponent(calendarId) + '/events?' + params;
  const response = await fetch(url, { headers, signal: AbortSignal.timeout(10000) });
  if (!response.ok) {
    const detail = await response.text();
    throw new Error('Google Calendar HTTP ' + response.status + ': ' + detail.slice(0, 160));
  }
  const json = await response.json();
  return (json.items || []).map(event => ({ ...event, _calendar_id: calendarId }));
}));
const tz = settings.timezone || undefined;
const dateKey = d => new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
const dateLabel = d => new Intl.DateTimeFormat('en-US', { timeZone: tz, weekday: 'short', month: 'short', day: 'numeric' }).format(d);
const timeLabel = d => new Intl.DateTimeFormat('en-US', { timeZone: tz, hour: 'numeric', minute: '2-digit', hour12: settings.time_format !== '24' }).format(d);
let events = batches.flat().filter(event => {
  if (event.status === 'cancelled') return false;
  if (settings.include_declined !== 'yes' && (event.attendees || []).some(a => a.self && a.responseStatus === 'declined')) return false;
  const haystack = ((event.summary || '') + ' ' + (event.description || '')).toLowerCase();
  return !ignored.some(phrase => haystack.includes(phrase));
}).map(event => {
  const allDay = Boolean(event.start && event.start.date);
  const startsAt = new Date(allDay ? event.start.date + 'T00:00:00' : event.start.dateTime);
  const endsAt = new Date(allDay ? event.end.date + 'T00:00:00' : event.end.dateTime);
  const hidden = settings.privacy_mode === 'busy_only' || event.visibility === 'private';
  return {
    id: event.id, calendar_id: event._calendar_id, title: hidden ? 'Busy' : (event.summary || 'Untitled event'),
    description: hidden ? '' : String(event.description || '').replace(/\s+/g, ' ').trim(),
    location: hidden ? '' : String(event.location || ''), all_day: allDay,
    start_ms: startsAt.getTime(), end_ms: endsAt.getTime(), date_key: dateKey(startsAt), date_label: dateLabel(startsAt),
    display_time: allDay ? 'All day' : timeLabel(startsAt) + '\u2013' + timeLabel(endsAt),
  };
}).sort((a, b) => a.start_ms - b.start_ms).slice(0, maxEvents);
const byDate = new Map();
for (const event of events) {
  if (!byDate.has(event.date_key)) byDate.set(event.date_key, []);
  byDate.get(event.date_key).push(event);
}
const dayCount = layout === 'agenda' ? 1 : layout === 'week' ? 7 : Math.min(daysAhead, 14);
const dayCursor = new Date(now); dayCursor.setHours(0, 0, 0, 0);
const days = [];
for (let i = 0; i < dayCount; i++) {
  const d = new Date(dayCursor); d.setDate(d.getDate() + i);
  const key = dateKey(d); days.push({ key, label: dateLabel(d), is_today: i === 0, events: byDate.get(key) || [] });
}
const monthBase = new Date(now.getFullYear(), now.getMonth(), 1);
const offset = (monthBase.getDay() - (settings.week_start === 'monday' ? 1 : 0) + 7) % 7;
const gridStart = new Date(monthBase); gridStart.setDate(gridStart.getDate() - offset);
const month_days = [];
for (let i = 0; i < 42; i++) {
  const d = new Date(gridStart); d.setDate(d.getDate() + i); const key = dateKey(d);
  month_days.push({ day: d.getDate(), key, in_month: d.getMonth() === monthBase.getMonth(), is_today: key === dateKey(now), events: byDate.get(key) || [] });
}
const weekdays = settings.week_start === 'monday' ? ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] : ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
return {
  events, days, month_days, weekdays, layout,
  month_label: new Intl.DateTimeFormat('en-US', { timeZone: tz, month: 'long', year: 'numeric' }).format(monthBase),
  generated_at: now.toISOString(), calendar_count: calendarIds.length,
};
